// Turn raw HTML into clean, line-by-line text so week-to-week changes can be compared.
const row = $('Has Page URL?').item.json;
const html = typeof $json.data === 'string' ? $json.data : '';
const failed = Boolean($json.error) || html.length < 200;

const decode = (s) => s
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)));

const text = decode(html
  // Drop code, menus and footers: they change often and carry no business meaning
  .replace(/<(script|style|noscript|svg|iframe|template|nav|footer)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  // Block-level tags become line breaks, everything else is stripped
  .replace(/<\/?(p|div|li|ul|ol|h[1-6]|tr|td|th|table|section|article|header|main|aside|br|hr|button|dt|dd|label|option|figcaption|blockquote)\b[^>]*>/gi, '\n')
  .replace(/<[^>]+>/g, ' '));

const lines = [];
const seen = new Set();
for (const raw of text.split('\n')) {
  const line = raw.replace(/\s+/g, ' ').trim();
  if (line.length < 2 || seen.has(line)) continue;
  seen.add(line);
  lines.push(line);
}

let error = '';
if (failed) {
  error = $json.error ? ($json.error.message || String($json.error)) : 'Empty or blocked response';
}

return {
  json: {
    competitor: row.Competitor,
    page_url: row['Page URL'],
    page_type: row['Page Type'] || 'Page',
    fetch_ok: !failed,
    fetch_error: error,
    // Google Sheets cells hold max 50,000 characters
    text: lines.join('\n').slice(0, 30000),
  },
};

// Compare every page with last week's snapshot and keep only the lines that changed.
const now = $now.toFormat('yyyy-MM-dd HH:mm');
const previous = {};
for (const item of $('Read Previous Snapshots').all()) {
  if (item.json['Page URL']) previous[item.json['Page URL']] = item.json;
}

const MAX_LINES = 40;
const clip = (lines) => lines.slice(0, MAX_LINES).map((l) => l.slice(0, 300)).join('\n');

return $input.all().map(({ json: page }, index) => {
  const old = previous[page.page_url] || {};
  const oldText = String(old.Content || '');
  let status;
  let added = [];
  let removed = [];

  if (!page.fetch_ok) {
    status = 'fetch failed';
  } else if (!oldText) {
    status = 'new';
  } else if (oldText === page.text) {
    status = 'unchanged';
  } else {
    const oldLines = new Set(oldText.split('\n'));
    const newLines = new Set(page.text.split('\n'));
    added = [...newLines].filter((l) => !oldLines.has(l));
    removed = [...oldLines].filter((l) => !newLines.has(l));
    status = added.length || removed.length ? 'changed' : 'unchanged';
  }

  let lastChanged = old['Last Changed'] || '';
  if (status === 'changed' || (status === 'new' && !lastChanged)) lastChanged = now;

  return {
    json: {
      // Columns written to the "Snapshots" sheet
      'Page URL': page.page_url,
      'Competitor': page.competitor,
      'Page Type': page.page_type,
      'Status': status === 'fetch failed' ? `fetch failed: ${page.fetch_error}`.slice(0, 200) : status,
      'Last Checked': now,
      'Last Changed': lastChanged,
      // Keep last good copy when a fetch fails, so a temporary error is not reported as a change
      'Content': page.fetch_ok ? page.text : oldText,
      // Used by the AI analyst only (not saved)
      status,
      added_count: added.length,
      removed_count: removed.length,
      added_lines: clip(added),
      removed_lines: clip(removed),
    },
    pairedItem: { item: index },
  };
});

