// Combine page checks, analysed changes and news into one research pack for the brief writer.
const settings = $('Settings').first().json;
const items = $input.all().map((i) => i.json);

const pages = items.filter((j) => j.status);
const changes = items.filter((j) => j.Headline);
const news = items.filter((j) => j.news_title);

const rank = { high: 0, medium: 1, low: 2 };
changes.sort((a, b) => (rank[a.Significance] ?? 3) - (rank[b.Significance] ?? 3));

// Keep the newest few headlines per competitor and drop duplicates
const maxNews = Number(settings.max_news_per_competitor) || 5;
const newsByCompetitor = {};
news
  .sort((a, b) => String(b.published).localeCompare(String(a.published)))
  .forEach((n) => {
    const list = (newsByCompetitor[n.competitor] ||= []);
    if (list.length < maxNews && !list.some((x) => x.news_title === n.news_title)) list.push(n);
  });

const changesText = changes.length
  ? changes.map((c) => `- [${String(c.Significance).toUpperCase()}] ${c.Competitor} (${c['Page Type']}): ${c.Headline}. ${c['What Changed']} Why it matters: ${c['Why It Matters']}`).join('\n')
  : 'No meaningful website changes detected this week.';

const newsText = Object.keys(newsByCompetitor).length
  ? Object.entries(newsByCompetitor)
      .map(([name, list]) => `${name}:\n` + list.map((n) => `  - ${n.news_title} (${String(n.published || '').slice(0, 10)})`).join('\n'))
      .join('\n')
  : 'No news coverage found this week.';

const countStatus = (s) => pages.filter((p) => p.status === s).length;
const competitors = new Set($('Active Rows Only').all().map((i) => i.json.Competitor));

return [{
  json: {
    week: $now.toFormat("kkkk-'W'WW"),
    period: `${$now.minus({ days: 7 }).toFormat('d LLL')} - ${$now.toFormat('d LLL yyyy')}`,
    stats: {
      competitors: competitors.size,
      pages_checked: pages.length,
      pages_changed: countStatus('changed'),
      meaningful_changes: changes.length,
      new_baselines: countStatus('new'),
      fetch_failed: countStatus('fetch failed'),
      news_items: Object.values(newsByCompetitor).reduce((sum, l) => sum + l.length, 0),
    },
    changes,
    news: newsByCompetitor,
    failed_pages: pages.filter((p) => p.status === 'fetch failed').map((p) => ({ competitor: p.Competitor, url: p['Page URL'], error: p.Status })),
    changes_text: changesText,
    news_text: newsText,
  },
}];

