// Render the AI brief as an HTML email and a short Slack message.
const brief = $json.output;
const pack = $('Build Research Pack').first().json;
const s = pack.stats;

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const slackEsc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const plural = (n, one, many = one + 's') => `${n} ${n === 1 ? one : many}`;
const colors = { high: '#d93025', medium: '#e37400', low: '#5f6368' };
const badge = (level) => `<span style="background:${colors[level] || '#5f6368'};color:#fff;border-radius:4px;padding:1px 6px;font-size:11px;text-transform:uppercase">${esc(level)}</span>`;
const h2 = (t) => `<h2 style="font-size:16px;margin:24px 0 8px;color:#202124">${t}</h2>`;
const list = (arr) => (arr && arr.length)
  ? `<ul style="margin:0;padding-left:20px">${arr.map((x) => `<li style="margin:4px 0">${esc(x)}</li>`).join('')}</ul>`
  : '<p style="color:#5f6368;margin:0">Nothing this week.</p>';

const stat = (value, label) => `<td style="text-align:center;padding:8px"><div style="font-size:22px;font-weight:bold;color:#202124">${value}</div><div style="font-size:12px;color:#5f6368">${label}</div></td>`;

const moves = (brief.top_moves || []).map((m) =>
  `<li style="margin:6px 0">${badge(m.impact)} <b>${esc(m.competitor)}</b>: ${esc(m.move)}</li>`).join('');

const changeRows = pack.changes.map((c) => `
  <tr>
    <td style="padding:8px;border-top:1px solid #e0e0e0;vertical-align:top;width:1%;white-space:nowrap">${badge(c.Significance)}</td>
    <td style="padding:8px;border-top:1px solid #e0e0e0"><b>${esc(c.Competitor)}</b> &middot; <a href="${esc(c['Page URL'])}">${esc(c['Page Type'])}</a><br>
      <b>${esc(c.Headline)}</b><br>${esc(c['What Changed'])}<br><i style="color:#5f6368">${esc(c['Why It Matters'])}</i></td>
  </tr>`).join('');

const newsBlocks = Object.entries(pack.news).map(([name, items]) => `
  <p style="margin:12px 0 4px"><b>${esc(name)}</b></p>
  <ul style="margin:0;padding-left:20px">${items.map((n) => `<li style="margin:3px 0"><a href="${esc(n.news_link)}">${esc(n.news_title)}</a></li>`).join('')}</ul>`).join('');

const failed = pack.failed_pages.length
  ? `<p style="color:#5f6368;font-size:12px;margin-top:24px">Could not fetch: ${pack.failed_pages.map((f) => esc(`${f.competitor} (${f.url})`)).join(', ')}. These sites may block automated requests.</p>`
  : '';

const html = `<!DOCTYPE html><html><body style="margin:0;background:#f1f3f4">
<div style="max-width:680px;margin:0 auto;padding:24px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#3c4043;background:#fff">
  <p style="margin:0;color:#5f6368;font-size:12px">COMPETITOR INTELLIGENCE &middot; ${esc(pack.week)} &middot; ${esc(pack.period)}</p>
  <h1 style="font-size:20px;margin:6px 0 16px;color:#202124">${esc(brief.subject)}</h1>
  <table style="width:100%;border-collapse:collapse;background:#f8f9fa;border-radius:8px"><tr>
    ${stat(s.competitors, s.competitors === 1 ? 'competitor' : 'competitors')}${stat(s.pages_checked, 'pages checked')}${stat(s.meaningful_changes, s.meaningful_changes === 1 ? 'meaningful change' : 'meaningful changes')}${stat(s.news_items, s.news_items === 1 ? 'news story' : 'news stories')}
  </tr></table>
  ${h2('Executive summary')}<p style="margin:0">${esc(brief.executive_summary)}</p>
  ${h2('Top competitor moves')}${moves ? `<ul style="margin:0;padding-left:20px;list-style:none">${moves}</ul>` : '<p style="color:#5f6368;margin:0">No major moves this week.</p>'}
  ${h2('Recommended actions')}${list(brief.recommended_actions)}
  ${h2('Threats')}${list(brief.threats)}
  ${h2('Opportunities')}${list(brief.opportunities)}
  ${pack.changes.length ? h2('Website changes') + `<table style="width:100%;border-collapse:collapse">${changeRows}</table>` : ''}
  ${newsBlocks ? h2('In the news') + newsBlocks : ''}
  ${failed}
  <p style="color:#9aa0a6;font-size:11px;margin-top:24px">Full change history is in the "Change Log" tab of your Google Sheet.</p>
</div></body></html>`;

const slackText = [
  `*${slackEsc(brief.subject)}*  (${slackEsc(pack.week)})`,
  slackEsc(brief.executive_summary),
  (brief.top_moves || []).length
    ? '*Top moves*\n' + brief.top_moves.map((m) => `• [${slackEsc(String(m.impact).toUpperCase())}] *${slackEsc(m.competitor)}*: ${slackEsc(m.move)}`).join('\n')
    : '',
  (brief.recommended_actions || []).length
    ? '*Do this week*\n' + brief.recommended_actions.map((a) => `• ${slackEsc(a)}`).join('\n')
    : '',
  `_${plural(s.pages_checked, 'page')} checked, ${plural(s.meaningful_changes, 'meaningful change')}, ${plural(s.news_items, 'news story', 'news stories')}. Full brief sent by email._`,
].filter(Boolean).join('\n\n');

return [{ json: { subject: brief.subject, html, slack_text: slackText } }];
